ons:\n           UNZIP:  [none]\n        UNZIPOPT:  [none]\n         ZIPINFO:  [none]\n      ZIPINFOOPT:  [none]\";s:4:\"path\";s:0:\"\";}s:4:\"path\";s:0:\"\";}}s:10:\"ziparchive\";a:2:{s:4:\"attr\";a:11:{s:4:\"name\";s:17:\"ZipArchive Method\";s:13:\"compatibility\";b:0;s:10:\"is_checker\";b:1;s:9:\"is_lister\";b:1;s:11:\"is_archiver\";b:0;s:13:\"is_unarchiver\";b:1;s:12:\"is_commenter\";b:1;s:9:\"is_zipper\";b:1;s:11:\"is_unzipper\";b:1;s:12:\"is_extractor\";b:1;s:20:\"can_add_virtual_file\";b:0;}s:5:\"param\";a:0:{}}s:6:\"pclzip\";a:2:{s:4:\"attr\";a:11:{s:4:\"name\";s:13:\"PclZip Method\";s:13:\"compatibility\";b:1;s:10:\"is_checker\";b:1;s:9:\"is_lister\";b:1;s:11:\"is_archiver\";b:1;s:13:\"is_unarchiver\";b:1;s:12:\"is_commenter\";b:1;s:9:\"is_zipper\";b:1;s:11:\"is_unzipper\";b:1;s:12:\"is_extractor\";b:1;s:20:\"can_add_virtual_file\";b:1;}s:5:\"param\";a:0:{}}}s:7:\"control\";a:1:{s:9:\"signature\";s:32:\"b4710d64fea0021ec833909fdefc61a9\";}}', 'no');
